function fmt(n){ if(n==null||n===''||isNaN(n)) return '—'; var v=Number(n); return (v<0?'-':'')+'$'+Math.abs(v).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,','); }
function fmtPct(n){ if(n==null||isNaN(n)) return '—'; var v=Number(n); return (v>0?'+':'')+v.toFixed(1)+'%'; }
function fmtNum(n){ if(n==null||isNaN(n)) return '—'; return Number(n).toLocaleString(undefined,{maximumFractionDigits:0}); }
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function sCls(v){ if(v==null) return ''; return v>0?'pos':(v<0?'neg':''); }
function tags(r){
  return (r.tou?' <span class="tou" title="Time-of-use — modeled on a default load shape, treat as an estimate">TOU*</span>':'')
       + (r.da?' <span class="da" title="Direct Access — needs a competitive supplier, not just a rate change">DA</span>':'')
       + (r.rtp?' <span class="rtp" title="Hourly / real-time pricing — modeled on a default shape, estimate">RTP*</span>':'');
}

var TAB = 'inventory';
var ACCT = '';
// Set the moment a Run is fired so the row can show it is working before the
// JSObject has had a chance to write anything back into the model.
var PENDING = '';
// The run this widget has already jumped to results for.
var SEEN_RUN = '';

// ---------------------------------------------------------------------------
// Accounts — the landing view. Everything the customer has, with the usage that
// would be priced, so someone can see what is there and choose what is worth
// spending minutes of tariff API time on before any of it runs.
// ---------------------------------------------------------------------------
function renderInventory(inv, busy){
  if(!inv.length) return '<div class="empty">Pick a customer to list its electric accounts.</div>';
  var runnable = inv.filter(function(r){ return r.runnable; }).length;
  var body = inv.map(function(r){
    var run = r.runnable
      ? '<button class="runbtn" data-key="'+esc(r.account_key)+'"'+(busy?' disabled':'')+'>'
          + (PENDING===String(r.account_key)?'Running…':'Run') + '</button>'
      // A blocked account keeps its cell rather than losing the column: the
      // reason sits next to it in Notes, so nothing is dropped without a word.
      : '<span class="cantrun" title="'+esc(r.blocker)+'">not modelable</span>';
    var streams = r.has_supply ? 'supply + delivery'
      : (r.full_service_annual>0 ? 'full service' : 'delivery only');
    return '<tr'+(r.issue?' class="hasissue"':'')+'>'
      + '<td title="'+esc(r.site)+'">'+esc(r.site)+'</td>'
      + '<td>'+esc(r.account_code)+'</td>'
      + '<td class="sub" title="'+esc(r.virtual_accounts)+'">'+esc(r.virtual_accounts||'—')+'</td>'
      + '<td>'+esc(r.utility||'—')+'</td>'
      + '<td class="sub" title="'+esc(r.supplier)+'">'+esc(r.supplier||'—')+'</td>'
      + '<td class="num">'+esc(r.zip||'—')+'</td>'
      + '<td class="num">'+esc(r.period_from||'—')+'</td>'
      + '<td class="num">'+esc(r.period_to||'—')+'</td>'
      + '<td class="num">'+esc(r.months)+'</td>'
      + '<td class="num">'+fmtNum(r.annual_kwh)+'</td>'
      + '<td class="num">'+fmtNum(r.peak_kw)+'</td>'
      + '<td class="num">'+fmt(r.actual_annual)+'</td>'
      + '<td class="sub">'+esc(r.account_status||'—')+'<div class="basis">'+streams+'</div></td>'
      + '<td class="issue">'+(r.issue?'<span class="warnpill'+(r.blocker?' stop':'')+'">'+esc(r.issue)+'</span>':'')+'</td>'
      + '<td class="ctr">'+run+'</td></tr>';
  }).join('');
  var total = inv.reduce(function(t,r){return t+(r.actual_annual||0);},0);
  var kwh   = inv.reduce(function(t,r){return t+(r.annual_kwh||0);},0);
  var blocked = inv.length - runnable;
  return '<div class="invbar">'
    + '<button class="runall" id="runall"'+(busy||!runnable?' disabled':'')+'>Run all ('+runnable+')</button>'
    + '<div class="invhdr">'+inv.length+' electric account(s) · '+fmtNum(kwh)+' kWh · '+fmt(total)
    + ' billed over the analysis window. Press <b>Run</b> on one account, or <b>Run all</b> to price every '
    + 'account that can be modeled. Pricing takes a minute or two per account — nothing is sent to the '
    + 'tariff API until you press one of them.'
    + (blocked ? ' <b>'+blocked+'</b> account(s) cannot be modeled; the reason is in the Notes column.' : '')
    + '</div></div>'
    + '<div class="scroll"><table class="tbl"><thead><tr>'
    + '<th>Location</th><th>Account</th><th>Virtual account</th><th>Utility</th><th>Supplier</th>'
    + '<th class="num">ZIP</th><th class="num">From</th><th class="num">To</th><th class="num">Mo</th>'
    + '<th class="num">kWh</th><th class="num">Peak kW</th><th class="num">Billed $</th>'
    + '<th>Status</th><th>Notes</th><th class="ctr">Analyse</th>'
    + '</tr></thead><tbody>'+body+'</tbody></table></div>';
}

// A run takes minutes. Without this the page looks frozen and people press the
// button again, so the message the JSObject writes as it works is shown here.
function renderProgress(p){
  if(!p) return '';
  return '<div class="progress"><span class="spin"></span>'+esc(p)+'</div>';
}

function renderRates(rows){
  if(!rows.length) return '<div class="empty">No rates modeled yet.</div>';
  var body = rows.map(function(r){
    return '<tr class="'+(r.best?'best':'')+'">'
      + '<td class="num">'+esc(r.rank)+'</td><td class="star">'+(r.best?'★':'')+'</td>'
      + '<td title="'+esc(r.utility)+'">'+esc(r.utility)+'</td>'
      + '<td title="'+esc(r.tariff)+'">'+esc(r.tariff)+(r.code?' <span class="code">('+esc(r.code)+')</span>':'')+tags(r)+'</td>'
      + '<td class="num">'+fmt(r.modeled_annual)+'</td><td class="num">'+fmt(r.modeled_energy)+'</td>'
      + '<td class="num">'+fmt(r.modeled_demand)+'</td><td class="num">'+fmt(r.actual_annual)+'</td>'
      + '<td class="num '+sCls(r.annual_savings)+'">'+fmt(r.annual_savings)+'</td>'
      + '<td class="num '+sCls(r.annual_savings)+'">'+fmtPct(r.savings_pct)+'</td>'
      + '<td class="status '+(r.status==='Error'?'err':'')+'">'+esc(r.status)+'</td></tr>';
  }).join('');
  return '<div class="scroll"><table class="tbl"><thead><tr><th class="num">#</th><th></th><th>Utility</th><th>Rate</th>'
    + '<th class="num">Modeled $</th><th class="num">Energy $</th><th class="num">Demand $</th>'
    + '<th class="num">Actual $</th><th class="num">Difference $</th><th class="num">Difference %</th><th>Status</th>'
    + '</tr></thead><tbody>'+body+'</tbody></table></div>'
    + '<div class="footnote">Every rate the account qualifies for, cheapest first. Difference is what switching to that rate would have changed over the same months; a blank means the rate is priced but not comparable, and the Status column says why.</div>';
}

function renderCards(cards){
  if(!cards.length) return '';
  return '<div class="cards">' + cards.map(function(c){
    return '<div class="card"><div class="cl">'+esc(c.label)+'</div>'
      + '<div class="cv '+esc(c.tone)+'">'+esc(c.value)+'</div>'
      + '<div class="cs">'+esc(c.sub)+'</div></div>';
  }).join('') + '</div>';
}

function renderPortfolio(rows){
  if(!rows.length) return '<div class="empty">No accounts match the current filters.</div>';
  var body = rows.map(function(r){
    // Contract vs utility is the headline: positive means the supply contract beat
    // the utility's rate. It is a different question from "best alternative".
    var cv = r.contract_savings;
    return '<tr class="'+(ACCT===String(r.location_id)?'sel':'')+'" data-loc="'+esc(r.location_id)+'">'
      + '<td title="'+esc(r.location)+'">'+esc(r.location)+'</td>'
      + '<td class="num">'+esc(r.zip)+'</td><td class="num">'+esc(r.months)+'</td>'
      + '<td class="num">'+fmtNum(r.annual_kwh)+'</td><td class="num">'+fmtNum(r.peak_kw)+'</td>'
      + '<td class="num">'+fmt(r.actual_annual)+'</td>'
      + '<td class="num sub">'+fmt(r.supply_annual)+'</td>'
      + '<td class="num sub">'+fmt(r.delivery_annual)+'</td>'
      + '<td class="num sub">'+fmt(r.full_service_annual)+'</td>'
      + '<td title="'+esc(r.utility_default)+'">'+esc(r.utility_default||'—')+'</td>'
      + '<td class="num">'+fmt(r.utility_default_annual)+'</td>'
      + '<td class="num '+sCls(cv)+'">'+fmt(cv)+'</td>'
      + '<td class="num '+sCls(cv)+'">'+fmtPct(r.contract_savings_pct)+'</td>'
      + '<td title="'+esc(r.tariff)+'">'+esc(r.tariff||'—')+tags(r)+'</td>'
      + '<td class="num">'+fmt(r.savings)+'</td>'
      + '<td class="status'+(r.status==='OK'?'':' warn')+'" title="'+esc(r.note)+'">'+esc(r.status)+'</td></tr>';
  }).join('');
  return '<div class="scroll"><table class="tbl rowsel"><thead><tr>'
    + '<th>Account / location</th><th class="num">ZIP</th><th class="num">Mo</th>'
    + '<th class="num">kWh</th><th class="num">Peak kW</th><th class="num">Actual paid $</th>'
    + '<th class="num">supply</th><th class="num">delivery</th><th class="num">full service</th>'
    + '<th>Utility rate</th><th class="num">Utility $</th>'
    + '<th class="num">Contract vs utility</th><th class="num">%</th>'
    + '<th>Best alternative rate</th><th class="num">Alt saving</th><th>Status</th>'
    + '</tr></thead><tbody>'+body+'</tbody></table></div>'
    + '<div class="footnote">Click a row for its charge-by-charge comparison. “Contract vs utility” is positive when the supply contract cost less than the utility rate shown, and applies only to accounts holding a competitive contract. An account billed <b>full service</b> is already on the utility and has no contract to compare — for those read “Best alternative rate”, which is what a different utility rate would have cost.</div>';
}

function renderLineItems(li){
  if(!li) return '<div class="empty">Select an account above to see its charge-by-charge comparison.</div>';
  if(li.error) return '<div class="empty">'+esc(li.error)+'</div>';
  var head = '<div class="lihdr"><b>'+esc(li.locationName)+'</b> · '+esc(li.windowFrom)+' → '+esc(li.windowTo)
    + ' ('+esc(li.monthCount)+' months) · compared against <b>'+esc(li.rate?li.rate.tariffName:'—')+'</b>'
    + (li.rate&&li.rate.isUtilityDefault?' <span class="pill">utility standard offer</span>'
       :' <span class="pill warn">cheapest qualifying rate, not a standard offer</span>')+'</div>';
  var warn='';
  if(li.structuralGap>0) warn += '<div class="warnbox">'+fmt(li.structuralGap)+' of billed charges ('
    + esc((li.gapGroups||[]).join(', '))+') have no counterpart in the modeled rate. Those would still be payable on the utility, '
    + 'so the difference below is overstated by roughly that much.</div>';
  if(li.varianceHigh) warn += '<div class="warnbox">The charge categories total '+fmt(li.actualTotal)
    + ' against a billed total of '+fmt(li.baselineTotal)+' ('+esc(li.variancePct)+'%). They should agree; investigate before relying on the split.</div>';
  var rows=(li.groups||[]).map(function(g){
    var det=(g.modeledLines||[]).map(function(x){
      return '<tr class="det"><td>↳ '+esc(x.name)+'</td><td class="num">'+fmtNum(x.qty)+'</td><td>'+esc(x.unit||'')+'</td>'
        + '<td class="num">—</td><td class="num">'+fmt(x.cost)+'</td><td></td></tr>'; }).join('');
    return '<tr class="grp"><td><b>'+esc(g.group)+'</b>'+(g.oneSided?' <span class="pill warn">one side only</span>':'')
      + '<div class="basis">'+esc(g.basis||'')+'</div></td>'
      + '<td></td><td></td><td class="num"><b>'+fmt(g.actual)+'</b></td><td class="num"><b>'+fmt(g.modeled)+'</b></td>'
      + '<td class="num '+sCls(-g.delta)+'"><b>'+fmt(g.delta)+'</b></td></tr>' + det;
  }).join('');
  var tot='<tr class="tot"><td><b>Total</b></td><td></td><td></td><td class="num"><b>'+fmt(li.actualTotal)+'</b></td>'
    + '<td class="num"><b>'+fmt(li.modeledTotal)+'</b></td><td class="num '+sCls(li.actualTotal-li.modeledTotal)+'"><b>'
    + fmt(li.modeledTotal-li.actualTotal)+'</b></td></tr>';
  return head + warn + '<div class="scroll"><table class="tbl li"><thead><tr><th>Charge group</th><th class="num">Qty</th><th>Unit</th>'
    + '<th class="num">Actual billed $</th><th class="num">Modeled $</th><th class="num">Difference</th></tr></thead>'
    + '<tbody>'+rows+tot+'</tbody></table></div>'
    + '<div class="footnote">The actual side comes from UBM\'s own charge categories on the monthly feed, which reconcile to the billed total on the Accounts tab. '
    + 'The billing line-item table is not used: it carries only a fraction of what was actually billed on these accounts. '
    + 'Indented rows are the modeled rate\'s own charge lines; a real bill words the same charge differently, so only the group and total rows compare like for like.</div>';
}

function renderSkipped(rows){
  if(!rows.length) return '<div class="empty">Every eligible account was modeled — nothing skipped.</div>';
  return '<div class="scroll"><table class="tbl"><thead><tr><th>Account / location</th><th class="num">ZIP</th>'
    + '<th class="num">Actual $</th><th>Why it was not modeled</th></tr></thead><tbody>'
    + rows.map(function(r){ return '<tr><td>'+esc(r.location)+'</td><td class="num">'+esc(r.zip)+'</td>'
        + '<td class="num">'+fmt(r.actual_annual)+'</td><td class="issue">'+esc(r.reason)+'</td></tr>'; }).join('')
    + '</tbody></table></div><div class="footnote">These accounts are excluded from every total above. They are listed rather than dropped so the account count in the results always reconciles against the account count on the Accounts tab.</div>';
}

function renderUsage(usage){
  if(!usage.length) return '';
  return '<details class="usage" open><summary>Billed months used for modeling ('+usage.length+')</summary>'
    + '<table class="tbl"><thead><tr><th>Month</th><th class="num">kWh</th><th class="num">Peak kW</th>'
    + '<th class="num">Supply $</th><th class="num">Delivery $</th><th class="num">Total $</th></tr></thead><tbody>'
    + usage.map(function(u){ return '<tr><td>'+esc(String(u.month).slice(0,7))+'</td><td class="num">'+fmtNum(u.kwh)+'</td>'
        + '<td class="num">'+fmtNum(u.kw)+'</td><td class="num">'+fmt(u.supply_charges)+'</td>'
        + '<td class="num">'+fmt(u.delivery_charges)+'</td><td class="num">'+fmt(u.actual_charges)+'</td></tr>'; }).join('')
    + '</tbody></table></details>';
}

function renderAllTariffs(list){
  if(!list.length) return '';
  return '<details class="usage"><summary>All tariffs Arcadia returned ('+list.length+') — includes riders and surcharges that are not modeled</summary>'
    + '<table class="tbl"><thead><tr><th>Utility</th><th>Tariff</th><th>Category</th><th>Type</th><th>Customer class</th><th class="ctr">Modeled</th></tr></thead><tbody>'
    + list.map(function(t){
        var cls = t.category==='Rate Class'?'cat-rc':(t.category==='Rider/Surcharge'?'cat-rd':'cat-ot');
        return '<tr><td>'+esc(t.utility)+'</td><td>'+esc(t.name)+(t.code?' <span class="code">('+esc(t.code)+')</span>':'')+tags(t)+'</td>'
          + '<td><span class="cat '+cls+'">'+esc(t.category)+'</span></td><td>'+esc(t.type)+'</td>'
          + '<td>'+esc(t.customerClass)+'</td><td class="ctr">'+(t.modeled?'<span class="tag-mod">modeled</span>':'')+'</td></tr>'; }).join('')
    + '</tbody></table></details>';
}

function render(model){
  var m = model || {};
  var portfolio = Array.isArray(m.portfolio)?m.portfolio:[];
  var cards = Array.isArray(m.cards)?m.cards:[];
  var hasResults = portfolio.length>0;
  var rows = Array.isArray(m.rows)?m.rows:[];
  var byLoc = m.lineItemsByLoc||{};
  var busy = !!m.loading;
  // A finished run clears whatever row was waiting on it.
  if(!busy) PENDING = '';
  // In results mode the drill-down lives in the widget, so switching accounts is
  // instant and never round-trips through the store.
  if(hasResults && (!ACCT || !portfolio.some(function(r){return String(r.location_id)===ACCT;})))
    ACCT = String(portfolio[0].location_id);
  var li = hasResults ? byLoc[ACCT] : m.lineItems;

  var inv = Array.isArray(m.inventory)?m.inventory:[];
  var tabs = [];
  if(inv.length) tabs.push(['inventory','Accounts ('+inv.length+')']);
  if(hasResults){
    tabs.push(['portfolio','Results ('+portfolio.length+')']);
    // The per-rate list is only meaningful for one account at a time; on a
    // single-account run it is the whole point of the screen, so it leads.
    if(rows.length) tabs.push(['rates','Rates ('+rows.length+')']);
    tabs.push(['lineitems','Actual vs modeled']);
    tabs.push(['skipped','Not modeled ('+(m.skipped||[]).length+')']);
  }
  if(!tabs.length) tabs=[['inventory','Accounts']];
  // A run that just finished should land on its results rather than leaving the
  // user on the account list wondering whether anything happened — but only ONCE
  // per run. Switching on every render would make the Accounts tab unclickable
  // afterwards, bouncing the user straight back to the results.
  if(hasResults && m.runId && m.runId !== SEEN_RUN){
    SEEN_RUN = m.runId;
    TAB = rows.length ? 'rates' : 'portfolio';
    ACCT = String(portfolio[0].location_id);
  }
  if(!tabs.some(function(t){return t[0]===TAB;})) TAB = tabs[0][0];

  var body;
  if(TAB==='inventory') body = renderInventory(inv, busy);
  else if(TAB==='portfolio') body = renderCards(cards) + renderPortfolio(portfolio);
  else if(TAB==='skipped') body = renderSkipped(m.skipped||[]);
  else if(TAB==='lineitems') body = renderLineItems(li);
  else body = renderRates(rows) + renderUsage(Array.isArray(m.usage)?m.usage:[]) + renderAllTariffs(Array.isArray(m.allTariffs)?m.allTariffs:[]);

  var root = document.getElementById('root'); if(!root) return;
  root.innerHTML = '<div class="tabs">'
    + tabs.map(function(t){ return '<button class="tab'+(TAB===t[0]?' on':'')+'" data-tab="'+t[0]+'">'+esc(t[1])+'</button>'; }).join('')
    + '</div>' + renderProgress(m.progress) + '<div class="body">'+body+'</div>';

  Array.prototype.forEach.call(root.querySelectorAll('.tab'), function(b){
    b.onclick = function(){ TAB = b.getAttribute('data-tab'); render(appsmith.model); };
  });
  Array.prototype.forEach.call(root.querySelectorAll('.rowsel tbody tr'), function(tr){
    tr.onclick = function(){ ACCT = tr.getAttribute('data-loc'); TAB = 'lineitems'; render(appsmith.model); };
  });
  // Hand the chosen account to the JSObject through the model, then fire the
  // event it listens on — triggerEvent carries no payload of its own.
  Array.prototype.forEach.call(root.querySelectorAll('.runbtn'), function(b){
    b.onclick = function(e){
      e.stopPropagation();
      PENDING = b.getAttribute('data-key');
      b.disabled = true; b.textContent = 'Running…';
      appsmith.updateModel({ runKey: PENDING });
      appsmith.triggerEvent('onRunAccount');
    };
  });
  var all = root.querySelector('#runall');
  if(all) all.onclick = function(){
    all.disabled = true; all.textContent = 'Running…';
    appsmith.triggerEvent('onRunAll');
  };
}
appsmith.onReady(function(){ render(appsmith.model); appsmith.onModelChange(render); });

