function renderSkipped(rows){
  if(!rows.length) return '<div class="empty">Every eligible account was modeled — nothing skipped.</div>';
  return '<div class="scroll"><table class="tbl"><thead><tr><th>Account / location</th><th class="num">ZIP</th>'
    + '<th class="num">Actual $</th><th>Why it was not modeled</th></tr></thead><tbody>'
    + rows.map(function(r){ return '<tr><td>'+esc(r.location)+'</td><td class="num">'+esc(r.zip)+'</td>'
        + '<td class="num">'+fmt(r.actual_annual)+'</td><td class="issue">'+esc(r.reason)+'</td></tr>'; }).join('')
    + '</tbody></table></div><div class="footnote">These accounts are excluded from every total above. They are listed rather than dropped so the account count in the results always reconciles against the account count on the Accounts tab.</div>';
}

function renderUsage(usage){
  if(!usage.length) return '';
  return '<details class="usage" open><summary>Billed months used for modeling ('+usage.length+')</summary>'
    + '<table class="tbl"><thead><tr><th>Month</th><th class="num">kWh</th><th class="num">Peak kW</th>'
    + '<th class="num">Supply $</th><th class="num">Delivery $</th><th class="num">Total $</th></tr></thead><tbody>'
    + usage.map(function(u){ return '<tr><td>'+esc(String(u.month).slice(0,7))+'</td><td class="num">'+fmtNum(u.kwh)+'</td>'
        + '<td class="num">'+fmtNum(u.kw)+'</td><td class="num">'+fmt(u.supply_charges)+'</td>'
        + '<td class="num">'+fmt(u.delivery_charges)+'</td><td class="num">'+fmt(u.actual_charges)+'</td></tr>'; }).join('')
    + '</tbody></table></details>';
}

function renderAllTariffs(list){
  if(!list.length) return '';
  return '<details class="usage"><summary>All tariffs Arcadia returned ('+list.length+') — includes riders and surcharges that are not modeled</summary>'
    + '<table class="tbl"><thead><tr><th>Utility</th><th>Tariff</th><th>Category</th><th>Type</th><th>Customer class</th><th class="ctr">Modeled</th></tr></thead><tbody>'
    + list.map(function(t){
        var cls = t.category==='Rate Class'?'cat-rc':(t.category==='Rider/Surcharge'?'cat-rd':'cat-ot');
        return '<tr><td>'+esc(t.utility)+'</td><td>'+esc(t.name)+(t.code?' <span class="code">('+esc(t.code)+')</span>':'')+tags(t)+'</td>'
          + '<td><span class="cat '+cls+'">'+esc(t.category)+'</span></td><td>'+esc(t.type)+'</td>'
          + '<td>'+esc(t.customerClass)+'</td><td class="ctr">'+(t.modeled?'<span class="tag-mod">modeled</span>':'')+'</td></tr>'; }).join('')
    + '</tbody></table></details>';
}

function render(model){
  var m = model || {};
  var portfolio = Array.isArray(m.portfolio)?m.portfolio:[];
  var cards = Array.isArray(m.cards)?m.cards:[];
  var hasResults = portfolio.length>0;
  var rows = Array.isArray(m.rows)?m.rows:[];
  var byLoc = m.lineItemsByLoc||{};
  var busy = !!m.loading;
  // A finished run clears whatever row was waiting on it.
  if(!busy) PENDING = '';
  // In results mode the drill-down lives in the widget, so switching accounts is
  // instant and never round-trips through the store.
  if(hasResults && (!ACCT || !portfolio.some(function(r){return String(r.location_id)===ACCT;})))
    ACCT = String(portfolio[0].location_id);
  var li = hasResults ? byLoc[ACCT] : m.lineItems;

  var inv = Array.isArray(m.inventory)?m.inventory:[];
  var tabs = [];
  if(inv.length) tabs.push(['inventory','Accounts ('+inv.length+')']);
  if(hasResults){
    tabs.push(['portfolio','Results ('+portfolio.length+')']);
    // The per-rate list is only meaningful for one account at a time; on a
    // single-account run it is the whole point of the screen, so it leads.
    if(rows.length) tabs.push(['rates','Rates ('+rows.length+')']);
    tabs.push(['lineitems','Actual vs modeled']);
    tabs.push(['skipped','Not modeled ('+(m.skipped||[]).length+')']);
  }
  if(!tabs.length) tabs=[['inventory','Accounts']];
  // A run that just finished should land on its results rather than leaving the
  // user on the account list wondering whether anything happened — but only ONCE
  // per run. Switching on every render would make the Accounts tab unclickable
  // afterwards, bouncing the user straight back to the results.
  if(hasResults && m.runId && m.runId !== SEEN_RUN){
    SEEN_RUN = m.runId;
    TAB = rows.length ? 'rates' : 'portfolio';
    ACCT = String(portfolio[0].location_id);
  }
  if(!tabs.some(function(t){return t[0]===TAB;})) TAB = tabs[0][0];

  var body;
  if(TAB==='inventory') body = renderInventory(inv, busy);
  else if(TAB==='portfolio') body = renderCards(cards) + renderPortfolio(portfolio);
  else if(TAB==='skipped') body = renderSkipped(m.skipped||[]);
  else if(TAB==='lineitems') body = renderLineItems(li);
  else body = renderRates(rows) + renderUsage(Array.isArray(m.usage)?m.usage:[]) + renderAllTariffs(Array.isArray(m.allTariffs)?m.allTariffs:[]);

  var root = document.getElementById('root'); if(!root) return;
  root.innerHTML = '<div class="tabs">'
    + tabs.map(function(t){ return '<button class="tab'+(TAB===t[0]?' on':'')+'" data-tab="'+t[0]+'">'+esc(t[1])+'</button>'; }).join('')
    + '</div>' + renderProgress(m.progress) + '<div class="body">'+body+'</div>';

  Array.prototype.forEach.call(root.querySelectorAll('.tab'), function(b){
    b.onclick = function(){ TAB = b.getAttribute('data-tab'); render(appsmith.model); };
  });
  Array.prototype.forEach.call(root.querySelectorAll('.rowsel tbody tr'), function(tr){
    tr.onclick = function(){ ACCT = tr.getAttribute('data-loc'); TAB = 'lineitems'; render(appsmith.model); };
  });
  // Hand the chosen account to the JSObject through the model, then fire the
  // event it listens on — triggerEvent carries no payload of its own.
  Array.prototype.forEach.call(root.querySelectorAll('.runbtn'), function(b){
    b.onclick = function(e){
      e.stopPropagation();
      PENDING = b.getAttribute('data-key');
      b.disabled = true; b.textContent = 'Running…';
      appsmith.updateModel({ runKey: PENDING });
      appsmith.triggerEvent('onRunAccount');
    };
  });
  var all = root.querySelector('#runall');
  if(all) all.onclick = function(){
    all.disabled = true; all.textContent = 'Running…';
    appsmith.triggerEvent('onRunAll');
  };
}
appsmith.onReady(function(){ render(appsmith.model); appsmith.onModelChange(render); });
